// src/components/charts/ForecastChart.jsx
import React, { useEffect, useRef } from "react";
import * as d3 from "d3";
import { COLORS } from "../../utils/colors";

export default function ForecastChart({ data, historicalData, title }) {
  const ref = useRef(null);

  useEffect(() => {
    if (!ref.current) return;
    if (!data || data.length === 0) {
      d3.select(ref.current).selectAll("*").remove();
      d3.select(ref.current)
        .append("text")
        .attr("x", "50%")
        .attr("y", "50%")
        .attr("text-anchor", "middle")
        .style("font-family", "Sarabun, sans-serif")
        .style("font-size", "14px")
        .style("fill", COLORS.sub)
        .text("No forecast data available");
      return;
    }

    const margin = { top: 30, right: 30, bottom: 50, left: 70 }; // Increased left margin
    const width = ref.current.clientWidth || 700;
    const height = 400; // Slightly taller for confidence interval
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    d3.select(ref.current).selectAll("*").remove();

    const svg = d3.select(ref.current)
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    // ==== 1. PREPARE DATA WITH PROPER SEQUENCE ====
    // Historical data: only up to the last actual data point
    const historicalDataFormatted = (historicalData || [])
      .filter(d => new Date(d.Date) < new Date("2026-01-01")) // Only historical
      .map(d => ({
        date: new Date(d.Date),
        price: d['Final Price'],
        isForecast: false
      }));

    // Sort historical by date
    historicalDataFormatted.sort((a, b) => a.date - b.date);

    // Forecast data: only 2026 onwards
    const forecastData = data
      .filter(d => new Date(d.Forecast_Date) >= new Date("2026-01-01"))
      .map(d => ({
        date: new Date(d.Forecast_Date),
        price: d.Forecasted_Price,
        isForecast: true
      }));

    // Sort forecast by date
    forecastData.sort((a, b) => a.date - b.date);

    // ==== 2. CREATE BRIDGE POINT ====
    // Find the last historical point and first forecast point
    const lastHistorical = historicalDataFormatted.length > 0 
      ? historicalDataFormatted[historicalDataFormatted.length - 1] 
      : null;

    const firstForecast = forecastData.length > 0 ? forecastData[0] : null;

    // Create bridge data point if both exist
    let bridgeData = [];
    if (lastHistorical && firstForecast) {
      // Use last historical price as bridge to avoid gap
      bridgeData = [{
        date: new Date(firstForecast.date),
        price: lastHistorical.price,
        isForecast: true,
        isBridge: true
      }];
    }

    // Combine: historical + bridge + forecast
    let allData = [...historicalDataFormatted];

    // Add bridge point if it exists and isn't the same as first forecast
    if (bridgeData.length > 0 && firstForecast) {
      const bridgePrice = bridgeData[0].price;
      const firstForecastPrice = firstForecast.price;

      // Only add bridge if prices are different (to show the transition)
      if (Math.abs(bridgePrice - firstForecastPrice) > 0.01) {
        allData.push(bridgeData[0]);
      }
    }

    // Add forecast data
    allData = [...allData, ...forecastData];

    // ==== 3. CALCULATE Y-AXIS DOMAIN WITH ROOM FOR CONFIDENCE ====
    const allPrices = allData.map(d => d.price);
    const yMin = Math.max(0, Math.min(...allPrices) * 0.85);
    const yMax = Math.max(...allPrices) * 1.15;

    // ==== 4. CREATE SCALES ====
    const xScale = d3.scaleTime()
      .domain(d3.extent(allData, d => d.date))
      .range([0, innerWidth]);

    const yScale = d3.scaleLinear()
      .domain([yMin, yMax])
      .range([innerHeight, 0]);

    // ==== 5. GRID LINES ====
    svg.append("g")
      .attr("class", "grid")
      .call(d3.axisLeft(yScale)
        .tickSize(-innerWidth)
        .tickFormat("")
      )
      .style("stroke", "#EEF2F7")
      .style("stroke-dasharray", "4,4");

    // ==== 6. DRAW CONFIDENCE INTERVAL (95% Ribbon) ====
    // Calculate confidence interval based on historical error
    // Using RMSE from metrics if available, or estimate from data
    const historicalPrices = historicalDataFormatted.map(d => d.price);
    const meanHistorical = historicalPrices.reduce((a, b) => a + b, 0) / historicalPrices.length;
    const stdDev = Math.sqrt(
      historicalPrices.reduce((a, b) => a + Math.pow(b - meanHistorical, 2), 0) / historicalPrices.length
    );
    const confidenceInterval = stdDev * 1.96; // 95% confidence

    // Create confidence band data for forecast period
    const confidenceData = forecastData.map(d => ({
      date: d.date,
      upper: d.price + confidenceInterval,
      lower: Math.max(0, d.price - confidenceInterval)
    }));

    // Draw confidence band
    if (confidenceData.length > 0) {
      const area = d3.area()
        .x(d => xScale(d.date))
        .y0(d => yScale(d.lower))
        .y1(d => yScale(d.upper))
        .curve(d3.curveMonotoneX);

      svg.append("path")
        .datum(confidenceData)
        .attr("d", area)
        .attr("fill", COLORS.accent)
        .attr("fill-opacity", 0.15)
        .attr("stroke", "none");
    }

    // ==== 7. DRAW HISTORICAL LINE ====
    if (historicalDataFormatted.length > 0) {
      const lineGen = d3.line()
        .x(d => xScale(d.date))
        .y(d => yScale(d.price))
        .curve(d3.curveMonotoneX);

      svg.append("path")
        .datum(historicalDataFormatted)
        .attr("d", lineGen)
        .attr("fill", "none")
        .attr("stroke", COLORS.accentDeep)
        .attr("stroke-width", 2.5)
        .attr("stroke-linecap", "round");

      // Historical dots
      svg.selectAll("circle.historical")
        .data(historicalDataFormatted)
        .enter()
        .append("circle")
        .attr("class", "historical")
        .attr("cx", d => xScale(d.date))
        .attr("cy", d => yScale(d.price))
        .attr("r", 4)
        .attr("fill", COLORS.accentDeep)
        .append("title")
        .text(d => `${d.date.toLocaleDateString()}: ₱${d.price.toFixed(2)}`);
    }

    // ==== 8. DRAW FORECAST LINE ====
    if (forecastData.length > 0) {
      const forecastLine = d3.line()
        .x(d => xScale(d.date))
        .y(d => yScale(d.price))
        .curve(d3.curveMonotoneX);

      // Draw forecast line
      svg.append("path")
        .datum(forecastData)
        .attr("d", forecastLine)
        .attr("fill", "none")
        .attr("stroke", COLORS.accent)
        .attr("stroke-width", 2.5)
        .attr("stroke-dasharray", "8,4")
        .attr("stroke-linecap", "round");

      // Forecast dots
      svg.selectAll("circle.forecast")
        .data(forecastData)
        .enter()
        .append("circle")
        .attr("class", "forecast")
        .attr("cx", d => xScale(d.date))
        .attr("cy", d => yScale(d.price))
        .attr("r", 5)
        .attr("fill", COLORS.accent)
        .attr("stroke", COLORS.white)
        .attr("stroke-width", 1.5)
        .append("title")
        .text(d => `${d.date.toLocaleDateString()}: ₱${d.price.toFixed(2)} (forecast)`);
    }

    // ==== 9. BRIDGE CONNECTION ====
    // Draw a connecting line from last historical to first forecast
    if (lastHistorical && firstForecast && bridgeData.length > 0) {
      const bridgeLine = d3.line()
        .x(d => xScale(d.date))
        .y(d => yScale(d.price))
        .curve(d3.curveLinear);

      const bridgePoints = [
        { date: lastHistorical.date, price: lastHistorical.price },
        { date: firstForecast.date, price: lastHistorical.price }
      ];

      svg.append("path")
        .datum(bridgePoints)
        .attr("d", bridgeLine)
        .attr("fill", "none")
        .attr("stroke", COLORS.accentDeep)
        .attr("stroke-width", 2)
        .attr("stroke-dasharray", "4,4")
        .attr("stroke-opacity", 0.6);
    }

    // ==== 10. AXES ====
    const xAxis = d3.axisBottom(xScale)
      .ticks(d3.timeMonth.every(2))
      .tickFormat(d3.timeFormat("%b %Y"));

    svg.append("g")
      .attr("transform", `translate(0,${innerHeight})`)
      .call(xAxis)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "11px")
      .style("color", COLORS.sub);

    // Y-Axis with proper formatting (no overlap)
    const yAxis = d3.axisLeft(yScale)
      .ticks(6)
      .tickFormat(d => `₱${d.toFixed(0)}`);

    svg.append("g")
      .call(yAxis)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "11px")
      .style("color", COLORS.sub);

    // ==== 11. LEGEND ====
    const legend = svg.append("g")
      .attr("transform", `translate(${innerWidth - 220}, -10)`);

    // Historical legend
    legend.append("line")
      .attr("x1", 0)
      .attr("y1", 0)
      .attr("x2", 25)
      .attr("y2", 0)
      .attr("stroke", COLORS.accentDeep)
      .attr("stroke-width", 2.5);

    legend.append("text")
      .attr("x", 32)
      .attr("y", 4)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "10px")
      .style("fill", COLORS.sub)
      .text("Historical");

    // Forecast legend
    legend.append("line")
      .attr("x1", 120)
      .attr("y1", 0)
      .attr("x2", 145)
      .attr("y2", 0)
      .attr("stroke", COLORS.accent)
      .attr("stroke-width", 2.5)
      .attr("stroke-dasharray", "8,4");

    legend.append("text")
      .attr("x", 152)
      .attr("y", 4)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "10px")
      .style("fill", COLORS.sub)
      .text("Forecast");

    // Confidence interval legend
    legend.append("rect")
      .attr("x", 0)
      .attr("y", 10)
      .attr("width", 25)
      .attr("height", 8)
      .attr("fill", COLORS.accent)
      .attr("fill-opacity", 0.15);

    legend.append("text")
      .attr("x", 32)
      .attr("y", 18)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "10px")
      .style("fill", COLORS.sub)
      .text("95% Confidence Interval");

  }, [data, historicalData]);

  return (
    <div 
      ref={ref} 
      style={{ 
        width: "100%", 
        height: 400, 
        background: COLORS.white, 
        borderRadius: 10,
        padding: "10px 0"
      }} 
    />
  );
}
